CREATE   VIEW [isurv].[vwIsurv_Invoices] AS

	SELECT
	 [Account_Num] AS 'Account No.'
	,[Full_Invoice_Amount_CUR] AS 'Full Invoice Amount CUR'
	,[Full_Invoice_Amount_GBP] AS 'Full Invoice Amount GBP'
	,[Invoice_Amount_CUR] AS 'Invoice Amount CUR'
	,[Invoice_Amount_GBP] AS 'Invoice Amount GBP'
	,[Settle_Amount_CUR] AS 'Settle Amount CUR'
	,[Settle_Amount_GBP] AS 'Settle Amount GBP'
	,[Inv_Full_Credit_Amount_CUR] AS 'Inv Full Credit Amount CUR'
	,[Inv_Full_Credit_Amount_GBP] AS 'Inv Full Credit Amount GBP'
	,[Inv_Credit_Amount_CUR] AS 'Inv Credit Amount CUR'
	,[Inv_Credit_Amount_GBP] AS 'Inv Credit Amount GBP'
	,[Order_Num.] AS 'Order No.'
	,[Invoice] AS 'Invoice'
	,[Voucher] AS 'Voucher'
	,[Trans_Date] AS 'Trans Date'
	,[Inv_Currency] AS 'Inv Currency'
	,[Exchange_Rate] AS 'Exchange Rate'
	,[Exchange_Adjustment] AS 'Exchange Adjustment'
	,[Inv_Payment_Method] AS 'Inv Payment Method'
	,[Rec_ID] AS 'Rec ID'
	,[Non_Subs_Amount_CUR] AS 'Non-Subs Amoun CUR'
	,[Non_Subs_Amount_GBP] AS 'Non-Subs Amoun GBP'
	,[Fully_Credited] AS 'Fully Credited'
	,[Paid_Amount_CUR] AS 'Paid Amount CUR'
	,[Paid_Amount_GBP] AS 'Paid Amount GBP'
	,[Balance_CUR] AS 'Balance CUR'
	,[Balance_GBP] AS 'Balance GBP'
	,[Payment_Status] AS 'Payment Status'
	,[Payment_Status_Rank] AS 'Payment Status Rank'
	FROM [isurv].[tblIsurv_Invoices]
